parameters.jsCode:
const raw = $input.item.json.body || $input.item.json || {};

const facultyName = raw.faculty_name || raw.facultyName || 'Dr. K. Senthil Nathan';
const department = (raw.department || 'IT').toUpperCase();
const leaveDate = raw.leave_date || raw.leaveDate || new Date().toISOString().split('T')[0];
const periods = raw.periods || [2];
const subjectName = raw.subject_name || raw.subject || 'Cloud Computing & DevOps';
const subjectCode = raw.subject_code || raw.code || 'IT601';
const roomNo = raw.room_no || raw.room || 'Lab 3';
const startTime = raw.start_time || '10:20';
const endTime = raw.end_time || '11:10';

const roster = [
  { id: 'T104', name: 'Dr. Mythili', email: 'mythili@suguna.edu', dept: 'IT', role: 'Assistant Professor', currentDailyHours: 1 },
  { id: 'T102', name: 'Dr. R. Ramesh', email: 'r.ramesh@suguna.edu', dept: 'IT', role: 'Associate Professor', currentDailyHours: 2 },
  { id: 'T103', name: 'Prof. S. Priya', email: 's.priya@suguna.edu', dept: 'IT', role: 'Assistant Professor', currentDailyHours: 3 },
  { id: 'T201', name: 'Prof. Alan Turing', email: 'turing@suguna.edu', dept: 'AIDS', role: 'Associate Professor', currentDailyHours: 2 },
  { id: 'T302', name: 'Dr. S. Rajasekaran', email: 'rajasekaran@suguna.edu', dept: 'CSE', role: 'Associate Professor', currentDailyHours: 2 }
];

const candidates = roster.filter(f => !f.name.toLowerCase().includes(facultyName.toLowerCase().split(' ')[1] || '---'));
let deptCandidates = candidates.filter(f => f.dept === department);
if (deptCandidates.length === 0) deptCandidates = candidates;
deptCandidates.sort((a, b) => a.currentDailyHours - b.currentDailyHours);

const substitute = deptCandidates[0] || candidates[0];
const dutyType = subjectName.toLowerCase().includes('lab') ? 'Lab Supervisor' : 'Subject Lecture';
const selectionReason = `Zero scheduling conflicts for target period (${startTime} - ${endTime}), department affinity (${substitute.dept}), and lowest daily workload (${substitute.currentDailyHours} hrs).`;

return {
  status: 'SUCCESS',
  faculty_name: facultyName,
  department: department,
  leave_date: leaveDate,
  periods: periods,
  subject_name: subjectName,
  subject_code: subjectCode,
  room_no: roomNo,
  start_time: startTime,
  end_time: endTime,
  match_verdict: {
    assigned_faculty_name: substitute.name,
    assigned_faculty_email: substitute.email,
    assigned_faculty_id: substitute.id,
    duty_type: dutyType,
    selection_reason: selectionReason
  },
  features: {}
};

const item = $input.item.json;
const sub = item.match_verdict;
const hodEmail = `hod_${item.department.toLowerCase()}@suguna.edu`;
const periodsStr = Array.isArray(item.periods) ? item.periods.join(', ') : item.periods;

item.features.gmail_alert = {
  to: sub.assigned_faculty_email,
  cc: hodEmail,
  subject: `Duty Allotment: Substitution for Period ${periodsStr} on ${item.leave_date}`,
  html_body: `<h3>Faculty Substitution Notice - Suguna College of Engineering</h3><p>Dear <b>${sub.assigned_faculty_name}</b>,</p><p>You have been allocated to handle <b>${item.subject_name}</b> (${item.subject_code}) on <b>${item.leave_date}</b> (Period ${periodsStr}, ${item.start_time} - ${item.end_time}) in <b>${item.room_no}</b> due to the leave of <b>${item.faculty_name}</b>.</p><p style="color: #059669;"><b>Status:</b> Zero-Conflict Automated Allocation Confirmed.</p>`
};

return item;

const item = $input.item.json;
const sub = item.match_verdict;

const cleanDate = item.leave_date.replace(/-/g, '');
const cleanStart = item.start_time.replace(':', '') + '00Z';
const cleanEnd = item.end_time.replace(':', '') + '00Z';

const calLink = `https://calendar.google.com/calendar/r/eventedit?text=${encodeURIComponent('Sub Class: ' + item.subject_name)}&dates=${cleanDate}T${cleanStart}/${cleanDate}T${cleanEnd}&details=${encodeURIComponent('Substitution for ' + item.faculty_name + ' (' + sub.duty_type + ')')}&location=${encodeURIComponent(item.room_no)}`;

item.features.google_calendar_event = {
  summary: `Sub Class: ${item.subject_name} (${item.room_no})`,
  description: `Handling substitution for Prof. ${item.faculty_name}. Department: ${item.department}. Duty: ${sub.duty_type}`,
  start_time: `${item.leave_date}T${item.start_time}:00`,
  end_time: `${item.leave_date}T${item.end_time}:00`,
  attendee_email: sub.assigned_faculty_email,
  calendar_link: calLink
};

return item;

const item = $input.item.json;
const sub = item.match_verdict;
const periodsStr = Array.isArray(item.periods) ? item.periods.join(', ') : item.periods;

item.features.in_app_portal_notification = {
  target_user_id: sub.assigned_faculty_id,
  title: 'New Class Allocation',
  message: `Period ${periodsStr} in ${item.room_no} assigned to you for ${item.subject_name}.`,
  priority: 'HIGH',
  timestamp: new Date().toISOString()
};

return item;

const item = $input.item.json;
const sub = item.match_verdict;

item.features.hod_workload_audit = {
  faculty_updated: sub.assigned_faculty_name,
  additional_hours_added: 1,
  audit_note: 'Extra substitution duty credited for semester faculty appraisal metrics.'
};

return {
  status: item.status,
  match_verdict: item.match_verdict,
  features: item.features
};
